import { colors, shadowLayerCss, shadows } from "./model.mjs";

const HEADER = `/**
 * Houston design tokens — semantic colour AND elevation custom properties.
 * AUTO-GENERATED by @houston/design-tokens. Do NOT edit by hand.
 * Source: tokens/*.json  ·  Rebuild: pnpm --filter @houston/design-tokens build
 *
 * These are the same --ht-* variable names the app and @houston-ai/* packages
 * already consume; the "@theme inline" bridge (in @houston-ai/core) re-exports
 * them to Tailwind's --color-* utilities. Light lives on :root, dark on
 * [data-theme="dark"] — mirroring how app/src/lib/theme.ts toggles the theme.
 * The light values are ALSO emitted under [data-theme="light"] so any subtree
 * can pin the light look regardless of the app theme (e.g. the sign-in card
 * pins [data-theme="dark"] the same way).
 *
 * Elevation rides the same three blocks as --ht-shadow-<tier>: a tier carries
 * its own light and dark box-shadow, so a component spends one shadow-<tier>
 * utility (bridged to Tailwind's --shadow-* namespace in @houston-ai/core) and
 * never a dark: fork.
 *
 * The pin works ONLY because the bridge is inline: that makes each utility read
 * var(--ht-*) directly (resolved at the consuming element), so a scoped
 * re-declaration of --ht-* re-resolves every Tailwind --color-* utility inside
 * that subtree. With a plain "@theme" the utilities would read a --color-* that
 * resolved once at :root and merely inherited down, and the pin would be inert
 * — see the note in ui/core/src/globals.css.
 */`;

function block(selector, entries) {
  const lines = entries.map(({ name, value }) => `  --ht-${name}: ${value};`);
  return `${selector} {\n${lines.join("\n")}\n}`;
}

/** One --ht-shadow-<tier> per elevation tier, layers joined into one value. */
const elevations = (tokens) =>
  shadows(tokens).map(({ name, layers }) => ({
    name: `shadow-${name}`,
    value: layers.map(shadowLayerCss).join(", "),
  }));

/** Every custom property one theme block carries: colours, then elevation. */
const vars = (tokens) => [...colors(tokens), ...elevations(tokens)];

/**
 * @param {import("./collect.mjs").collect} _
 * @param {{ path: string[], value: string }[]} light
 * @param {{ path: string[], value: string }[]} dark
 */
export function buildCss(light, dark) {
  return [
    HEADER,
    "",
    block(":root", vars(light)),
    "",
    block('[data-theme="light"]', vars(light)),
    "",
    block('[data-theme="dark"]', vars(dark)),
    "",
  ].join("\n");
}
